      SUBROUTINE BEAMINCC     CALCULATES THE INITIAL BEAM ENVELOPE FROM THE DATACC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'BETAC.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM1B.CIN'      INCLUDE 'ELM1C.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'ETAP.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R3P.CIN'      INCLUDE 'SI.CIN'CC     LOCAL VARIABLESC      INTEGER         IAX, IAY, IBX, IBY, IDATA, IEX, IEY      INTEGER         IPLNO, IPLUSJ, IRI      INTEGER         J, JPL1, K      REAL            DATAR, E, RINEW, SIJJC------------------------------------------------------------------------------           C      IPLNO = IPTOJ(8)      RMSADD = IPLNO .NE. 0      IF (RMSADD) GO TO 160      NEXT = IDATA(ISTOR(NUM+1))      IRI = IPTOJ(7)      RI = DATAR(I+IRI)*UNITI(11)      IF (.NOT. LPRF) PREF = RI      IF (SM .EQ. 0.0) THEN        BETA = 1.0        GAMMA = 2.0E5      ELSE        E = SQRT(RI**2 + SM**2)        BETA = RI/E        GAMMA = E/SM      ENDIF      LTWISS = IPTOJ(10) .NE. 0 .AND. IPTOJ(13) .NE. 0C      DO 105 J = 1, 6      CO(J) = 0.0  105 CONTINUEC      IF (R2P .OR. R3P) CALL UPDAT2      IF (NORD3 .LT. 1) GO TO 150      IF (ACCEL .OR. LTWISS) GO TO 130      NOPH = .TRUE.C      DO 110 J = 1, 6      IPLUSJ = I + J      SIJJ = (DATAR(IPLUSJ)*UBEAM(J))**2      IF (SIJJ .GT. 0.0) NOPH = .FALSE.      SI(J,J) = SIJJ  110 CONTINUEC      DO 120 J = 1, 5      JPL1 = J + 1      DO 120 K = JPL1, 6      SI(J,K) = 0.0      SI(K,J) = 0.0  120 CONTINUE      GO TO 140C  130 DO 131 J = 1, 6      DO 131 K = 1, 6      SI(J,K) = 0.0  131 CONTINUEC      IF (ACCEL .AND. .NOT. LTWISS) THEN        BETAX = DATAR(I+1)*UBEAM(1)/UBEAM(2)        ALPHAX = DATAR(I+2)        EPSX = 1.0        BETAY = DATAR(I+3)*UBEAM(3)/UBEAM(4)        ALPHAY = DATAR(I+4)        EPSY = 1.0      ELSE        IBX = IPTOJ(10)        BETAX = DATAR(I+IBX)*UBEAM(1)/UBEAM(2)        IAX = IPTOJ(11)        ALPHAX = DATAR(I+IAX)        IEX = IPTOJ(12)        IF (IEX .NE. 0.0) THEN          EPSX = DATAR(I+IEX)*UBEAM(1)*UBEAM(2)        ELSE          EPSX = 1.0        ENDIF        IBY = IPTOJ(13)        BETAY = DATAR(I+IBY)*UBEAM(3)/UBEAM(4)        IAY = IPTOJ(14)        ALPHAY = DATAR(I+IAY)        IEY = IPTOJ(15)        IF (IEY .NE. 0) THEN          EPSY = DATAR(I+IEY)*UBEAM(3)*UBEAM(4)        ELSE          EPSY = 1.0        ENDIF      ENDIFC      SI(1,1) = EPSX*BETAX      SI(1,2) = - EPSX*ALPHAX      SI(2,1) = SI(1,2)      SI(2,2) = EPSX*(1.0 + ALPHAX**2)/BETAX      SI(3,3) = EPSY*BETAY      SI(3,4) = - EPSY*ALPHAY      SI(4,3) = SI(3,4)      SI(4,4) = EPSY*(1.0 + ALPHAY**2)/BETAYC  140 IF (RAY) GO TO 150      DO 145 J = 1, 5  145 ETA(J) = 0.0      ETA(6) = UBEAM(6)      RAY = .TRUE.C  150 CALL INIT1      GO TO 170C  160 IF (R2P .OR. R3P) CALL UPDAT2      IF (ACCEL .OR. LTWISS) GO TO 180      IF (NORD3 .GT. 1) GO TO 190      RINEW = RI + DATA(I+7)*UNITI(11)      PREF = PREF*RINEW/RI      RI = RINEWC      IF (NORD3 .LT. 1) GO TO 200      DO 165 J = 1, 6      IPLUSJ = I + J      SI(J,J) = SI(J,J) + (DATA(IPLUSJ)*UBEAM(J))**2      IF (SI(J,J) .GT. 0.0) NOPH = .FALSE.  165 CONTINUE      RECENT = .FALSE.C  170 EPSX = SQRT(SI(1,1)*SI(2,2) - SI(1,2)**2)      EPSY = SQRT(SI(3,3)*SI(4,4) - SI(3,4)**2)      GO TO 200C  180 WRITE (NOUT,9001) 9001 FORMAT (' *** ERROR *** RMS ADDITION NOT PERMITTED WITH',     1        ' ACCELERATOR NOTATION')      FLUSHL = .TRUE.      GO TO 200C  190 WRITE (NOUT,9015) 9015 FORMAT (' *** ERROR *** RMS ADDITION NOT PERMITTED WITH',     1        ' HIGHER-ORDER MATRIX DISPLAY')      FLUSHL = .TRUE.C  200 RETURN      END